    /// <summary>
    /// MPJ_4054_CustAgingReport
    /// </summary>
    /// <param name="args">
    /// get the CustAgingReport class 
    /// </param>
    [PostHandlerFor(classStr(CustAgingReportDP), methodStr(CustAgingReportDP, processReport))]
    public static void CustAgingReportDP_Post_processReport(XppPrePostArgs args)
    {
        CustAgingReportDP               metCustAgingReportDP    =   args.getThis() as CustAgingReportDP;
        CustAgingReportTmp              metCustAgingReportTmp   =   metCustAgingReportDP.getCustAgingReportTmp();
        METCustTable                    metCustTable;
        CustTrans                       metCustTrans;
        CustTransOpen                   metCustTransOpen;
        CustDispute                     metCustDispute;
        METCustTransSummary             metCustTransSummary;
        METCustTotalDisputeReasonLegal  metCustTotalDisputeReasonLegal;
        CustTable                       custTable;

        update_recordset metCustAgingReportTmp
            setting  
            METIndustryKey      = metCustTable.IndustryKey   
        join AccountNum,IndustryKey from metCustTable
            where  metCustTable.AccountNum == metCustAgingReportTmp.AccountNum;
        
        ttsbegin;
        while select forupdate metCustAgingReportTmp // update recordset doesn;t work well with aggregate functions
        {
            select  sum(AmountCur) from  metCustTransOpen
                join metCustTrans
                    where metCustTrans.RecId == metCustTransOpen.RefRecId
                        && metCustTrans.AccountNum == metCustAgingReportTmp.AccountNum
                join metCustDispute
                    where metCustDispute.CustTrans == metCustTrans.RecId
                    &&    metCustDispute.Status    == CustVendDisputeStatus::Disputed;

            metCustAgingReportTmp.METTotalInDispute = metCustTransOpen.AmountCur;
            metCustAgingReportTmp.update();
        }
        ttscommit;
        
        
        update_recordset metCustAgingReportTmp
            setting
            METUnallocatedCash = metCustTransSummary.AmountCur - metCustTransSummary.SettleAmountMST
            join  metCustTransSummary 
                where metCustTransSummary.AccountNum == metCustAgingReportTmp.AccountNum
                &&    metCustTransSummary.TransType  == LedgerTransType::Payment;

        // MPJ-16249- New column Disputed + Legal status
        update_recordset metCustAgingReportTmp
            setting
            METTotalInDisputeLegal   = metCustTotalDisputeReasonLegal.AmountMST,
            Balance01                = 0,
            Balance02                = 0,
            Balance03                = 0,
            Balance04                = 0,
            Balance05                = 0,
            Balance06                = 0,
            Balance07                = 0,
            METTotalOverDue          = 0
        join metCustTotalDisputeReasonLegal
            where metCustTotalDisputeReasonLegal.AccountNum == metCustAgingReportTmp.AccountNum;        
        // MPJ-16249- New column Disputed + Legal status

        update_recordset metCustAgingReportTmp
            setting
            METTotalOverDue     = (metCustAgingReportTmp.Balance03 + metCustAgingReportTmp.Balance04 + metCustAgingReportTmp.Balance05 +
                                   metCustAgingReportTmp.Balance06 + metCustAgingReportTmp.Balance07 + metCustAgingReportTmp.METTotalInDisputeLegal);
        
        // MPJ-16249- New column creditlimit
        update_recordset metCustAgingReportTmp
            setting
            METCreditLimit = custTable.CreditMax
        join CreditMax from custTable
            where custTable.AccountNum == metCustAgingReportTmp.AccountNum;

        // MPJ-16249- New column OverDuePercentage
        update_recordset metCustAgingReportTmp
            setting
            METTotalOverDuePercent = (metCustAgingReportTmp.METTotalOverDue / metCustAgingReportTmp.Balance01) * 100
            where metCustAgingReportTmp.Balance01 != 0;

        update_recordset metCustAgingReportTmp
            setting
            Balance01 = (metCustAgingReportTmp.Balance01 + metCustAgingReportTmp.METTotalInDisputeLegal + metCustAgingReportTmp.METUnallocatedCash);
    }
